enum Stage { IF, ID, EX, MEM, WB };

struct PipelineReg {
    int inst_id = -1;
    // Data/Control signals carried forward...
};

// Pipeline Registers holding results between stages
PipelineReg R_ID_EX, R_EX_MEM, R_MEM_WB;

void pipeline_shift(PipelineReg I_fetch) {
    // Overlap/Shift occurs on clock edge
    R_MEM_WB = R_EX_MEM;  // WB processes old MEM
    R_EX_MEM = R_ID_EX;   // MEM processes old EX
    R_ID_EX = I_fetch;    // EX processes old ID
    // New instruction enters IF stage
}
